int replace_network_table(struct net *net, const void __user *user, unsigned int len)
{
    struct tmp_table_info *tmp;
    int ret;
    size_t num_entries;

    if (len < sizeof(struct tmp_table_info))
        return -EINVAL;

    if (len % sizeof(struct table_entry))
        return -EINVAL;

    num_entries = (len - sizeof(struct tmp_table_info)) / sizeof(struct table_entry);
    if (num_entries > MAX_TABLE_ENTRIES)
        return -ENOMEM;

    tmp = kmalloc(len, GFP_KERNEL);
    if (!tmp)
        return -ENOMEM;

    if (copy_from_user(tmp, user, len)) {
        ret = -EFAULT;
        goto out_free;
    }

    if (tmp->header.size != len) {
        ret = -EINVAL;
        goto out_free;
    }

    ret = allocate_table_memory(net, tmp);
    if (ret)
        goto out_free;

    ret = copy_entries_from_user(net, tmp, user + sizeof(struct tmp_table_info), num_entries);
    if (ret)
        goto out_free;

    ret = finish_table_replacement(net, tmp);
    if (ret)
        goto out_free;

    kfree(tmp);
    return 0;

out_free:
    free_allocated_table_memory(net);
    kfree(tmp);
    return ret;
}

int replace_network_table(struct net *net, const void __user *user, unsigned int len)
{
    struct temp_table_data *temp;
    int num_entries;
    int ret = 0;
    int i;

    if (len < sizeof(struct temp_table_data))
        return -EINVAL;

    temp = kmalloc(len, GFP_KERNEL);
    if (!temp)
        return -ENOMEM;

    if (copy_from_user(temp, user, len)) {
        kfree(temp);
        return -EFAULT;
    }

    num_entries = len / sizeof(struct table_entry);
    if (len % sizeof(struct table_entry) || num_entries <= 0) {
        kfree(temp);
        return -EINVAL;
    }

    if (num_entries > MAX_TABLE_ENTRIES) {
        kfree(temp);
        return -EOVERFLOW;
    }

    struct table *new_table = allocate_table(num_entries);
    if (!new_table) {
        kfree(temp);
        return -ENOMEM;
    }

    for (i = 0; i < num_entries; i++) {
        if (copy_from_user(&new_table->entries[i], &temp->entries[i], sizeof(struct table_entry))) {
            free_table(new_table);
            kfree(temp);
            return -EFAULT;
        }
    }

    ret = finish_table_replacement(net, new_table);
    if (ret < 0) {
        free_table(new_table);
        kfree(temp);
        return ret;
    }

    kfree(temp);
    return 0;
}

