int replace_network_table(struct net *net, const void __user *user, unsigned int len) {
    struct tmp_table_info *tmp;
    int num_entries, ret;

    if (len % sizeof(struct table_entry) != 0)
        return -EINVAL;

    num_entries = len / sizeof(struct table_entry);
    if (num_entries <= 0)
        return -EINVAL;

    tmp = kmalloc(len, GFP_KERNEL);
    if (!tmp)
        return -ENOMEM;

    if (copy_from_user(tmp, user, len)) {
        kfree(tmp);
        return -EFAULT;
    }

    if (check_entry_overflow(tmp, num_entries) < 0) {
        kfree(tmp);
        return -EINVAL;
    }

    ret = allocate_and_populate_table(tmp, net, num_entries);
    if (ret < 0) {
        kfree(tmp);
        return ret;
    }

    ret = finalize_table_replacement(net, tmp);
    if (ret < 0) {
        free_allocated_table(net);
        kfree(tmp);
        return ret;
    }

    kfree(tmp);
    return 0;
}

int replace_network_table(struct net *net, const void __user *user, unsigned int len)
{
    int err;
    void *tmp;
    struct table_info *new_table;

    if (!access_ok(VERIFY_READ, user, len))
        return -EFAULT;

    tmp = memdup_user(user, len);
    if (IS_ERR(tmp))
        return PTR_ERR(tmp);

    if (len % sizeof(struct table_entry)) {
        kfree(tmp);
        return -EINVAL;
    }

    new_table = kmalloc(sizeof(*new_table), GFP_KERNEL);
    if (!new_table) {
        kfree(tmp);
        return -ENOMEM;
    }

    new_table->num_entries = len / sizeof(struct table_entry);
    if (new_table->num_entries > MAX_ENTRIES) {
        kfree(new_table);
        kfree(tmp);
        return -EINVAL;
    }

    memcpy(new_table->entries, tmp, len);
    kfree(tmp);

    err = finalize_table_replacement(net, new_table);
    if (err) {
        kfree(new_table);
        return err;
    }

    return 0;
}
